1	"use strict";
2	// Nxeon Mod Builder build service.
3	//
4	// POST /builds                 {id, prompt, mcVersion, pluginName?, baseBuildId?, changeRequest?} -> 202
5	// GET  /builds/:id             status + events + result
6	// GET  /builds/:id/artifact    the plugin .jar
7	// GET  /builds/:id/source?path=src/main/java/...   one source file (text)
8	// GET  /builds/:id/source.zip  all source (+ Gradle template) as a zip
9	// POST /builds/:id/cancel
10	// GET  /health
11	//
12	// Every route except /health needs `Authorization: Bearer $MODBUILDER_API_KEY`.
13	// AI auth is whatever the Claude CLI finds in the environment:
14	//   CLAUDE_CODE_OAUTH_TOKEN (owner subscription, testing) or ANTHROPIC_API_KEY
15	//   (paid API, production). Swapping is a one-line change in the env file.
16	
17	const http = require("http");
18	const fs = require("fs");
19	const path = require("path");
20	const crypto = require("crypto");
21	const { spawn, execFileSync } = require("child_process");
22	const YAML = require("yaml");
23	const { scanBytecode, scanSource, scanSecrets } = require("./scan");
24	const P = require("./prompts");
25	
26	const PORT = int(process.env.PORT, 3000);
27	const DATA = process.env.MB_DATA || "/data";
28	const BUILDS = path.join(DATA, "builds");
29	// Live workspaces sit outside /data so the model's Read-deny on //data/** keeps
30	// it away from other users' finished sources and the build records.
31	const WORK = process.env.MB_WORK || "/work";
32	const TEMPLATE = "/opt/mb/template";
33	const CP_DIR = "/opt/mb/classpath";
34	const API_KEY = process.env.MODBUILDER_API_KEY || "";
35	const MODEL = process.env.MB_MODEL || "sonnet";
36	const REPAIR_MODEL = process.env.MB_REPAIR_MODEL || MODEL;
37	const CONCURRENCY = int(process.env.MB_CONCURRENCY, 2);
38	const MAX_REPAIRS = int(process.env.MB_MAX_REPAIRS, 3);
39	const BUILD_BUDGET_USD = num(process.env.MB_BUILD_BUDGET_USD, 4);
40	const CALL_BUDGET_USD = num(process.env.MB_CALL_BUDGET_USD, 2.5);
41	const BUILD_TIMEOUT_MS = int(process.env.MB_BUILD_TIMEOUT_S, 1200) * 1000;
42	const CALL_TIMEOUT_MS = int(process.env.MB_CALL_TIMEOUT_S, 600) * 1000;
43	const MAX_TURNS = int(process.env.MB_MAX_TURNS, 60);
44	const VERSIONS = (process.env.MB_VERSIONS || "1.21.11").split(/\s+/).filter(Boolean);
45	const SECRETS = [process.env.CLAUDE_CODE_OAUTH_TOKEN, process.env.ANTHROPIC_API_KEY, API_KEY].filter(Boolean);
46	
47	function int(v, d) { const n = parseInt(v || "", 10); return Number.isFinite(n) ? n : d; }
48	function num(v, d) { const n = parseFloat(v || ""); return Number.isFinite(n) ? n : d; }
49	function now() { return new Date().toISOString(); }
50	function log(level, msg, meta = {}) { process.stderr.write(JSON.stringify({ ts: now(), level, msg, ...meta }) + "\n"); }
51	
52	fs.mkdirSync(BUILDS, { recursive: true });
53	fs.mkdirSync(WORK, { recursive: true });
54	
55	// ---------------------------------------------------------------- state ----
56	const records = new Map(); // id -> record (also persisted to build.json)
57	const queue = [];
58	const running = new Map(); // id -> { child, cancelled }
59	
60	function dirOf(id) { return path.join(BUILDS, id); }
61	function save(rec) {
62	  rec.updatedAt = now();
63	  const f = path.join(dirOf(rec.id), "build.json");
64	  fs.writeFileSync(f + ".tmp", JSON.stringify(rec, null, 2));
65	  fs.renameSync(f + ".tmp", f);
66	}
67	function event(rec, stage, message, detail) {
68	  rec.events.push({ at: now(), stage, message, ...(detail ? { detail: String(detail).slice(0, 4000) } : {}) });
69	  if (rec.events.length > 400) rec.events.splice(1, rec.events.length - 400);
70	  save(rec);
71	}
72	function setStage(rec, status, message) { rec.status = status; event(rec, status, message); }
73	
74	// Load persisted builds; anything mid-flight when the service stopped is failed.
75	for (const id of fs.readdirSync(BUILDS)) {
76	  try {
77	    const rec = JSON.parse(fs.readFileSync(path.join(dirOf(id), "build.json"), "utf8"));
78	    if (!["succeeded", "failed"].includes(rec.status)) {
79	      rec.status = "failed";
80	      rec.error = "The build service restarted while this build was running. Please try again.";
81	      rec.errorCode = "interrupted";
82	      rec.finishedAt = now();
83	      rec.events.push({ at: now(), stage: "failed", message: "Interrupted by a service restart" });
84	      save(rec);
85	    }
86	    records.set(id, rec);
87	  } catch { /* ignore broken dirs */ }
88	}
89	
90	// ------------------------------------------------------------- helpers ----
91	function copyDir(src, dst, filter = () => true) {
92	  fs.mkdirSync(dst, { recursive: true });
93	  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
94	    const s = path.join(src, e.name), d = path.join(dst, e.name);
95	    if (!filter(s, e)) continue;
96	    if (e.isDirectory()) copyDir(s, d, filter);
97	    else if (e.isFile()) fs.copyFileSync(s, d);
98	  }
99	}
100	function listFiles(root, rel = "") {
101	  const out = [];
102	  const abs = path.join(root, rel);
103	  if (!fs.existsSync(abs)) return out;
104	  for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
105	    const r = path.posix.join(rel, e.name);
106	    if (e.isSymbolicLink()) { fs.rmSync(path.join(root, r), { force: true }); continue; }
107	    if (e.isDirectory()) out.push(...listFiles(root, r));
108	    else if (e.isFile()) out.push({ rel: r, abs: path.join(root, r), size: fs.statSync(path.join(root, r)).size });
109	  }
110	  return out;
111	}
112	function rmrf(p) { fs.rmSync(p, { recursive: true, force: true }); }
113	function childEnv(withAi) {
114	  const env = { PATH: process.env.PATH, HOME: process.env.HOME || "/home/claude", JAVA_HOME: process.env.JAVA_HOME, LANG: "C.UTF-8" };
115	  if (withAi) {
116	    for (const k of ["CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY", "ANTHROPIC_BASE_URL"]) if (process.env[k]) env[k] = process.env[k];
117	    env.DISABLE_AUTOUPDATER = "1";
118	    env.CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC = "1";
119	  }
120	  return env;
121	}
122	function run(cmd, args, opts) {
123	  return new Promise((resolve) => {
124	    const child = spawn(cmd, args, { cwd: opts.cwd, env: opts.env, stdio: ["ignore", "pipe", "pipe"] });
125	    if (opts.track) opts.track.child = child;
126	    let out = "", err = "";
127	    child.stdout.on("data", (d) => { out += d; if (opts.onStdout) opts.onStdout(d); if (out.length > 8e6) out = out.slice(-4e6); });
128	    child.stderr.on("data", (d) => { err += d; if (err.length > 2e6) err = err.slice(-1e6); });
129	    const t = setTimeout(() => { child.kill("SIGKILL"); err += "\n[timeout]"; }, opts.timeout);
130	    child.on("close", (code, signal) => { clearTimeout(t); resolve({ code, signal, out, err, timedOut: err.endsWith("[timeout]") }); });
131	    child.on("error", (e) => { clearTimeout(t); resolve({ code: -1, out, err: String(e) }); });
132	  });
133	}
134	
135	// ------------------------------------------------------------ AI calls ----
136	const SETTINGS = JSON.stringify({
137	  permissions: {
138	    deny: ["Bash", "WebFetch", "WebSearch", "Read(//proc/**)", "Read(//etc/**)", "Read(//home/**)", "Read(//opt/**)", "Read(//root/**)", "Read(//run/**)", "Read(//data/**)"],
139	  },
140	});
141	
142	async function callClaude(rec, ctl, ws, prompt, { resume, model }) {
143	  const args = ["-p", "--output-format", "stream-json", "--verbose",
144	    "--permission-mode", "acceptEdits",
145	    "--tools", "Read", "Write", "Edit", "Glob", "Grep",
146	    "--settings", SETTINGS, "--strict-mcp-config",
147	    "--model", model, "--max-turns", String(MAX_TURNS),
148	    "--max-budget-usd", String(Math.max(0.2, Math.min(CALL_BUDGET_USD, BUILD_BUDGET_USD - rec.costUsd))),
149	    "--system-prompt", P.systemPrompt(rec.mcVersion)];
150	  if (resume) args.push("--resume", resume); else args.push("--session-id", rec.sessionId);
151	  args.push("--", prompt);
152	
153	  let buf = "", result = null, wroteAny = false;
154	  const onStdout = (d) => {
155	    buf += d;
156	    let i;
157	    while ((i = buf.indexOf("\n")) >= 0) {
158	      const line = buf.slice(0, i); buf = buf.slice(i + 1);
159	      if (!line.trim()) continue;
160	      let msg; try { msg = JSON.parse(line); } catch { continue; }
161	      if (msg.type === "assistant" && msg.message && Array.isArray(msg.message.content)) {
162	        for (const c of msg.message.content) {
163	          if (c.type !== "tool_use") continue;
164	          const fp = c.input && (c.input.file_path || c.input.path || "");
165	          const rel = fp ? path.relative(ws, fp) || fp : "";
166	          const short = rel.split("/").pop();
167	          if (c.name === "Write" || c.name === "Edit" || c.name === "MultiEdit") {
168	            if (!wroteAny && rec.status === "planning") setStage(rec, "coding", "Writing the plugin code");
169	            wroteAny = true;
170	            event(rec, rec.status, `${c.name === "Write" ? "Wrote" : "Edited"} ${short}`);
171	          } else if (c.name === "Read" && short) event(rec, rec.status, `Reading ${short}`);
172	        }
173	      } else if (msg.type === "system" && msg.subtype === "init" && msg.model) {
174	        rec.resolvedModel = msg.model;
175	      } else if (msg.type === "result") result = msg;
176	    }
177	  };
178	  const r = await run("claude", args, { cwd: ws, env: childEnv(true), timeout: CALL_TIMEOUT_MS, onStdout, track: ctl });
179	  ctl.child = null;
180	  const cost = result && typeof result.total_cost_usd === "number" ? result.total_cost_usd : 0;
181	  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
182	  rec.aiCalls.push({ at: now(), model, costUsd: cost, turns: result ? result.num_turns : null, durationMs: result ? result.duration_ms : null, subtype: result ? result.subtype : null, exit: r.code });
183	  if (result && result.usage) {
184	    const u = result.usage;
185	    rec.tokens.input += (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.cache_read_input_tokens || 0);
186	    rec.tokens.output += u.output_tokens || 0;
187	  }
188	  save(rec);
189	  if (ctl.cancelled) throw fail("cancelled", "Build cancelled.");
190	  if (!result) {
191	    log("error", "claude produced no result", { id: rec.id, code: r.code, err: r.err.slice(-2000) });
192	    const authish = /auth|401|403|login|credit|quota|rate.?limit|overloaded/i.test(r.err);
193	    throw fail(r.timedOut ? "timeout" : "ai_unavailable", r.timedOut ? "The AI took too long on this one. Try a smaller request." : "The AI builder is unavailable right now. Please try again in a few minutes.", authish ? "AI service error" : r.err.slice(-1500));
194	  }
195	  if (result.subtype === "error_max_budget_usd") throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request or split it into two plugins.");
196	  if (result.is_error && result.subtype !== "error_max_turns") {
197	    throw fail("ai_unavailable", "The AI builder hit an error. Please try again in a few minutes.", String(result.result || result.subtype).slice(0, 1500));
198	  }
199	  return result;
200	}
201	
202	function fail(code, message, detail) { const e = new Error(message); e.code = code; e.detail = detail; return e; }
203	
204	// ------------------------------------------------------- validation/compile
205	function readSummary(ws) {
206	  const f = path.join(ws, "modbuilder.json");
207	  if (!fs.existsSync(f)) return null;
208	  try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return { _invalid: true }; }
209	}
210	
211	// Keep the model inside its lane: only src/main/** and modbuilder.json survive,
212	// Gradle files always come from the pinned template.
213	function sanitizeWorkspace(ws, rec) {
214	  for (const f of listFiles(ws)) {
215	    const ok = f.rel.startsWith("src/main/java/") || f.rel.startsWith("src/main/resources/") || f.rel === "modbuilder.json"
216	      || f.rel === "build.gradle.kts" || f.rel === "settings.gradle.kts";
217	    if (!ok) { fs.rmSync(f.abs, { force: true }); event(rec, rec.status, `Removed unexpected file ${f.rel}`); }
218	  }
219	  for (const g of ["build.gradle.kts", "settings.gradle.kts"]) fs.copyFileSync(path.join(TEMPLATE, g), path.join(ws, g));
220	}
221	
222	function validate(ws, rec) {
223	  const problems = [];
224	  const res = path.join(ws, "src/main/resources");
225	  const ymlPath = path.join(res, "plugin.yml");
226	  if (fs.existsSync(path.join(res, "paper-plugin.yml"))) problems.push("Use plugin.yml, not paper-plugin.yml: delete src/main/resources/paper-plugin.yml.");
227	  if (!fs.existsSync(ymlPath)) return { problems: ["src/main/resources/plugin.yml is missing."], yml: null };
228	  let yml;
229	  try { yml = YAML.parse(fs.readFileSync(ymlPath, "utf8")); } catch (e) { return { problems: [`plugin.yml is not valid YAML: ${e.message}`], yml: null }; }
230	  if (!yml || typeof yml !== "object") return { problems: ["plugin.yml is empty."], yml: null };
231	  if (!/^[A-Za-z0-9_]{1,40}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
232	  if (!yml.version) problems.push("plugin.yml needs a version.");
233	  const main = String(yml.main || "");
234	  if (!/^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)+$/.test(main)) problems.push("plugin.yml main must be a fully-qualified class name.");
235	  else if (!fs.existsSync(path.join(ws, "src/main/java", main.replace(/\./g, "/") + ".java"))) problems.push(`plugin.yml main is ${main} but src/main/java/${main.replace(/\./g, "/")}.java does not exist.`);
236	  if (/^(org\.bukkit|io\.papermc|net\.minecraft|com\.destroystokyo|net\.kyori)\./.test(main)) problems.push("The main class must be in your own package.");
237	  const apiMajor = rec.mcVersion.split(".").slice(0, 2).join(".");
238	  if (String(yml["api-version"] || "") !== apiMajor) {
239	    // Mechanical fix, not worth a model round-trip.
240	    yml["api-version"] = apiMajor;
241	    fs.writeFileSync(ymlPath, YAML.stringify(yml));
242	  }
243	  // getCommand("x") without a plugin.yml entry returns null at runtime -> NPE on enable.
244	  const declared = new Set(Object.keys((yml.commands && typeof yml.commands === "object") ? yml.commands : {}).map((s) => s.toLowerCase()));
245	  const java = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java"));
246	  if (!java.length) problems.push("No Java source files were written.");
247	  for (const f of java) {
248	    const text = fs.readFileSync(f.abs, "utf8");
249	    for (const m of text.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) {
250	      if (!declared.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}" (it would crash on enable).`);
251	    }
252	    if (/^\s*public\s+final\s+class\s+\w+\s+extends\s+JavaPlugin/m.test(text)) problems.push(`${f.rel}: the main class must not be final.`);
253	  }
254	  const total = listFiles(ws, "src").reduce((a, f) => a + f.size, 0);
255	  if (total > 1.5 * 1024 * 1024) problems.push("The source is too large (over 1.5 MB).");
256	  return { problems: [...new Set(problems)], yml };
257	}
258	
259	async function compile(ws, rec, ctl) {
260	  const out = path.join(ws, "build/classes");
261	  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
262	  const cp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
263	  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
264	  const r = await run("javac", ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
265	    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
266	  ctl.child = null;
267	  const output = (r.err + r.out).split(ws + "/").join("");
268	  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
269	  // Resources (plugin.yml, config.yml, ...)
270	  copyDir(path.join(ws, "src/main/resources"), out);
271	  const jar = path.join(ws, "build/plugin.jar");
272	  const j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
273	  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
274	  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
275	  return { ok: true, jar, classes: out, warnings };
276	}
277	
278	// ------------------------------------------------------------ pipeline ----
279	async function runBuild(rec) {
280	  const ctl = { child: null, cancelled: false };
281	  running.set(rec.id, ctl);
282	  const started = Date.now();
283	  rec.startedAt = now();
284	  const ws = path.join(WORK, rec.id);
285	  const finalWs = path.join(dirOf(rec.id), "ws");
286	  const killer = setTimeout(() => { ctl.cancelled = true; ctl.timeout = true; if (ctl.child) ctl.child.kill("SIGKILL"); }, BUILD_TIMEOUT_MS);
287	  try {
288	    rmrf(ws);
289	    if (rec.baseBuildId) {
290	      const baseWs = path.join(dirOf(rec.baseBuildId), "ws");
291	      if (!fs.existsSync(baseWs)) throw fail("bad_request", "The earlier build this change is based on is no longer available.");
292	      copyDir(baseWs, ws, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === baseWs));
293	      setStage(rec, "planning", "Reading your existing plugin and planning the change");
294	    } else {
295	      copyDir(TEMPLATE, ws);
296	      setStage(rec, "planning", "Planning the plugin from your description");
297	    }
298	
299	    let prompt = rec.baseBuildId ? P.changePrompt(rec) : P.initialPrompt(rec);
300	    let resume = null;
301	    let repairs = 0;
302	    let safetyRepairs = 0;
303	    let lastErr = "";
304	    for (;;) {
305	      rec.attempts += 1;
306	      await callClaude(rec, ctl, ws, prompt, { resume, model: resume ? REPAIR_MODEL : MODEL });
307	      resume = rec.sessionId;
308	
309	      const summary = readSummary(ws);
310	      if (summary && summary.refused) {
311	        throw fail("refused", `We can't build this one. ${String(summary.reason || "It goes against our plugin safety rules.").slice(0, 300)}`);
312	      }
313	      sanitizeWorkspace(ws, rec);
314	
315	      const secretHits = scanSecrets(listFiles(ws), SECRETS);
316	      if (secretHits.length) {
317	        rmrf(ws);
318	        log("error", "secret material found in generated source", { id: rec.id, files: secretHits });
319	        throw fail("safety", "The generated code was blocked by our safety checks.", "secret-scan");
320	      }
321	
322	      setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", rec.attempts > 1 ? `Checking the fix (attempt ${rec.attempts})` : "Checking the plugin files");
323	      const v = validate(ws, rec);
324	      let problem = null;
325	      if (v.problems.length) {
326	        problem = { kind: "compile", text: v.problems.map((p) => `- ${p}`).join("\n"), say: `${v.problems.length} setup problem${v.problems.length > 1 ? "s" : ""} found` };
327	      } else {
328	        setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", `Compiling against Paper ${rec.mcVersion}${rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}`);
329	        const c = await compile(ws, rec, ctl);
330	        if (ctl.cancelled) throw fail(ctl.timeout ? "timeout" : "cancelled", ctl.timeout ? "This build ran out of time." : "Build cancelled.");
331	        if (!c.ok) {
332	          const n = (c.errors.match(/ error(s)?$/m) || [])[0];
333	          const count = (c.errors.match(/^\d+ errors?$/m) || ["compile errors"])[0];
334	          problem = { kind: "compile", text: c.errors, say: `Compiler found ${count}` };
335	          void n;
336	        } else {
337	          event(rec, rec.status, "Compiled successfully");
338	          setStage(rec, "scanning", "Running the safety check");
339	          const findings = [...scanBytecode(c.classes), ...scanSource(listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")))];
340	          const blocks = findings.filter((f) => f.severity === "block");
341	          if (blocks.length) {
342	            if (safetyRepairs >= 1 || repairs >= MAX_REPAIRS) {
343	              rec.safety = { verdict: "block", findings };
344	              throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}. Try rewording the request without that part.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
345	            }
346	            safetyRepairs += 1;
347	            problem = { kind: "safety", text: blocks.map((b) => `- ${b.where}: ${b.message} (${b.evidence})`).join("\n"), say: `Safety check flagged ${blocks.length} thing${blocks.length > 1 ? "s" : ""}` };
348	          } else {
349	            const warns = findings.filter((f) => f.severity === "warn");
350	            rec.safety = { verdict: warns.length ? "warn" : "pass", findings };
351	            event(rec, "scanning", warns.length ? `Safety check passed with ${warns.length} note${warns.length > 1 ? "s" : ""}` : "Safety check passed: no network, no commands outside the game, own folder only");
352	            await finish(rec, ws, c, v.yml);
353	            return;
354	          }
355	        }
356	      }
357	      // ---- repair loop
358	      lastErr = problem.text;
359	      if (repairs >= MAX_REPAIRS) throw fail("compile", `We couldn't get this plugin to build after ${rec.attempts} tries. Try a simpler description, or split it into smaller plugins.`, lastErr);
360	      if (rec.costUsd >= BUILD_BUDGET_USD) throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request.", lastErr);
361	      repairs += 1;
362	      rec.repairs = repairs;
363	      setStage(rec, "repairing", `${problem.say}. Fixing it automatically (fix ${repairs} of ${MAX_REPAIRS})`);
364	      event(rec, "repairing", "Error details", problem.text.slice(0, 3000));
365	      prompt = P.repairPrompt(problem.kind, problem.text.slice(0, 8000));
366	    }
367	  } catch (e) {
368	    rec.status = "failed";
369	    rec.errorCode = ctl.timeout ? "timeout" : (e.code || "internal");
370	    rec.error = ctl.timeout ? "This build ran out of time. Try a smaller request." : (e.code ? e.message : "Something went wrong on our side. Please try again.");
