cd /tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/javap && cat > ../fields.py <<'EOF'
import re,sys,glob,os
V=["1.21.1","1.21.4","1.21.8","1.21.11"]
def fields(v,c):
    t=open(f"{v}/{c}.txt").read()
    return set(re.findall(r"public static final [\w.$<>]+ (\w+);",t))
def methods(v,c):
    t=open(f"{v}/{c}.txt").read()
    return set(l.strip() for l in t.splitlines() if "(" in l)
mode=sys.argv[1]; c=sys.argv[2]
if mode=="f":
    sets={v:fields(v,c) for v in V}
    allf=set().union(*sets.values())
    for f in sorted(allf):
        pres=[v for v in V if f in sets[v]]
        if len(pres)!=4: print(f, "->", ",".join(pres))
    print("common:",len(set.intersection(*sets.values())))
else:
    sets={v:methods(v,c) for v in V}
    allm=set().union(*sets.values())
    for m in sorted(allm):
        pres=[v for v in V if m in sets[v]]
        if len(pres)!=4: print(",".join(pres),"|",m)
EOF
for c in org.bukkit.attribute.Attribute org.bukkit.Particle org.bukkit.potion.PotionEffectType org.bukkit.enchantments.Enchantment; do echo "##### $c"; python3 ../fields.py f $c; done

