import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { realUser } from "@/lib/auth";
import { isPreviewUser } from "@/lib/preview-access";
import { svcHealth } from "@/lib/modbuilder/client";
import { PageHeader, Badge, StatCard, timeAgo } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  const ok = await isPreviewUser(await realUser().catch(() => null), "modbuilder");
  return { title: ok ? "Mod Builder builds" : "Page not found", robots: { index: false, follow: false } };
}

const tone = (s: string): "green" | "red" | "brand" => (s === "succeeded" ? "green" : s === "failed" ? "red" : "brand");

/**
 * AI Mod Builder: every build with its AI cost. Private preview, so this page
 * is URL-only (no admin-nav entry) and gated on the preview allowlist as well
 * as the fleet area.
 */
export default async function AdminModBuilderPage() {
  await requireArea("fleet");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const [rows, agg, byStatus, health] = await Promise.all([
    db.modBuild.findMany({ orderBy: { createdAt: "desc" }, take: 200 }),
    db.modBuild.aggregate({ _sum: { costUsd: true }, _avg: { costUsd: true, durationMs: true }, _count: { _all: true } }),
    db.modBuild.groupBy({ by: ["status"], _count: { _all: true } }),
    svcHealth(),
  ]);
  const users = await db.user.findMany({ where: { id: { in: Array.from(new Set(rows.map((r) => r.userId))) } }, select: { id: true, email: true } });
  const email = new Map(users.map((u) => [u.id, u.email]));
  const n = (s: string) => byStatus.find((x) => x.status === s)?._count._all ?? 0;
  const done = n("succeeded") + n("failed");

  return (
    <div>
      <PageHeader title="AI Mod Builder" sub="Private preview. Every build, its AI spend (API-equivalent USD as reported by the build service) and outcome.">
        {health?.ok ? <Badge tone="green">service online · {String(health.auth)}</Badge> : <Badge tone="red">service unreachable</Badge>}
      </PageHeader>
      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Builds" value={String(agg._count._all)} delta={`${n("succeeded")} ok · ${n("failed")} failed`} />
        <StatCard label="Success rate" value={done ? `${Math.round((n("succeeded") / done) * 100)}%` : "–"} />
        <StatCard label="Total AI cost" value={`$${(agg._sum.costUsd ?? 0).toFixed(2)}`} delta={`avg $${(agg._avg.costUsd ?? 0).toFixed(3)}/build`} />
        <StatCard label="Avg time" value={agg._avg.durationMs ? `${Math.round(agg._avg.durationMs / 1000)}s` : "–"} />
      </div>
      <div className="card overflow-x-auto">
        {rows.length === 0 ? <p className="text-sm text-slate-500">No builds yet.</p> : (
          <table className="w-full text-left text-sm [&_td]:px-2 [&_th]:px-2">
            <thead className="text-xs text-slate-500">
              <tr><th className="py-1">When</th><th>User</th><th>Plugin</th><th>Status</th><th>Tries</th><th>Time</th><th className="text-right">Cost</th><th>Prompt</th></tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id} className="border-t border-slate-800/40 align-top">
                  <td className="py-1.5 whitespace-nowrap">{timeAgo(r.createdAt)}</td>
                  <td className="whitespace-nowrap">{email.get(r.userId) ?? r.userId}</td>
                  <td className="whitespace-nowrap">{r.pluginName ?? "–"}{r.version ? ` v${r.version}` : ""}{r.baseBuildId ? " (change)" : ""}</td>
                  <td><Badge tone={tone(r.status)}>{r.status}</Badge>{r.errorCode ? <span className="ml-1 text-xs text-slate-500">{r.errorCode}</span> : null}</td>
                  <td>{r.attempts}</td>
                  <td className="whitespace-nowrap">{r.durationMs ? `${Math.round(r.durationMs / 1000)}s` : "–"}</td>
                  <td className="text-right tabular-nums">${r.costUsd.toFixed(3)}</td>
                  <td className="max-w-[420px] truncate text-xs text-slate-400" title={r.changeRequest || r.prompt}>{r.changeRequest || r.prompt}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
// ModBuild persistence: mirror the build service's status into the DB row and
// keep the finished jar on the primary. Used by the API routes (sync on read,
// while someone watches) and by the worker sweep (so a build finishes even if
// nobody keeps the page open). Plain module: safe in the worker.
import { createHash } from "node:crypto";
import { mkdir, writeFile, rename, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { ModBuild, Prisma } from "@prisma/client";
import { db } from "../db";
import { svcArtifact, svcGet, type ServiceBuild } from "./client";
import { isTerminal, type ModBuildResult, type ModBuildView } from "./types";

export const MODBUILD_DIR = process.env.NXEON_MODBUILD_DIR || "/var/lib/nxeon/modbuilds";
export const jarPathFor = (id: string) => join(MODBUILD_DIR, `${id}.jar`);

// A build the service never heard back on for this long is failed (the VM was
// rebuilt, the tunnel down for an hour, ...). Generous: real builds take 1-10 min.
const STALE_MS = 2 * 60 * 60 * 1000;

function toResult(s: ServiceBuild): ModBuildResult {
  return {
    summary: s.summary,
    commands: (s.commands || []) as ModBuildResult["commands"],
    permissions: (s.permissions || []) as ModBuildResult["permissions"],
    config: (s.config || []) as ModBuildResult["config"],
    warnings: s.warnings || [],
    files: s.files || [],
    safety: (s.safety as ModBuildResult["safety"]) || null,
    events: (s.events || []).slice(-150),
    repairs: s.repairs || 0,
    queuePosition: s.queuePosition || 0,
    errorDetail: s.errorDetail ? String(s.errorDetail).slice(0, 6000) : null,
  };
}

/** Pull the service's view of one build into its row. Never throws for an unreachable service. */
export async function syncBuild(row: ModBuild): Promise<ModBuild> {
  if (isTerminal(row.status)) return row;
  let s: ServiceBuild | null;
  try {
    s = await svcGet(row.id);
  } catch {
    if (Date.now() - row.createdAt.getTime() > STALE_MS) {
      return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "unreachable", error: "We lost contact with the builder while this was running. Please try again.", finishedAt: new Date() } });
    }
    return row;
  }
  if (!s) {
    return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "lost", error: "The builder has no record of this build. Please try again.", finishedAt: new Date() } });
  }
  const data: Prisma.ModBuildUpdateInput = {
    status: s.status,
    attempts: s.attempts || 0,
    costUsd: s.costUsd || 0,
    durationMs: s.durationMs || null,
    pluginName: s.pluginName || row.pluginName,
    version: s.version || row.version,
    error: s.error,
    errorCode: s.errorCode,
    result: toResult(s) as unknown as Prisma.InputJsonValue,
  };
  if (s.status === "succeeded" && s.jar) {
    // Store the jar before flipping the row to succeeded, so "succeeded" always
    // means "downloadable".
    const bytes = await svcArtifact(row.id);
    const sha = createHash("sha256").update(bytes).digest("hex");
    if (sha !== s.jar.sha256) throw new Error("artifact checksum mismatch");
    await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
    const dest = jarPathFor(row.id);
    await writeFile(dest + ".part", bytes, { mode: 0o640 });
    await rename(dest + ".part", dest);
    Object.assign(data, { jarName: s.jar.name, jarSize: bytes.length, jarSha256: sha, jarPath: dest });
  }
  if (isTerminal(s.status)) data.finishedAt = s.finishedAt ? new Date(s.finishedAt) : new Date();
  return db.modBuild.update({ where: { id: row.id }, data });
}

export async function readJar(row: ModBuild): Promise<Buffer> {
  if (!row.jarPath || row.status !== "succeeded") throw new Error("no jar");
  return readFile(row.jarPath);
}

/** Worker sweep: advance every in-flight build. */
export async function sweepModBuilds(): Promise<void> {
  const rows = await db.modBuild.findMany({ where: { status: { notIn: ["succeeded", "failed"] } }, take: 20, orderBy: { createdAt: "asc" } });
  for (const r of rows) {
    try { await syncBuild(r); } catch (e) { console.error("[modbuilder] sync failed", r.id, (e as Error).message); }
  }
}

export function toView(row: ModBuild): ModBuildView {
  return {
    id: row.id,
    status: row.status as ModBuildView["status"],
    prompt: row.prompt,
    changeRequest: row.changeRequest,
    baseBuildId: row.baseBuildId,
    rootBuildId: row.rootBuildId,
    mcVersion: row.mcVersion,
    pluginName: row.pluginName,
    version: row.version,
    error: row.error,
    errorCode: row.errorCode,
    attempts: row.attempts,
    durationMs: row.durationMs,
    jarName: row.jarName,
    jarSize: row.jarSize,
    createdAt: row.createdAt.toISOString(),
    finishedAt: row.finishedAt ? row.finishedAt.toISOString() : null,
    result: (row.result as unknown as ModBuildResult) ?? null,
    lastInstall: (row.lastInstall as unknown as ModBuildView["lastInstall"]) ?? null,
  };
}
