/** Raw service record (see services/modbuilder/server.js). Only the fields the portal reads. */
export type ServiceBuild = {
  id: string; status: string; error: string | null; errorCode: string | null; errorDetail?: string | null;
  attempts: number; repairs: number; costUsd: number; durationMs: number; pluginName: string | null; version?: string;
  jar: { name: string; size: number; sha256: string } | null;
  summary: { tagline: string; text: string; howToUse: string[]; limitations: string[]; changes: string } | null;
  commands: unknown[]; permissions: unknown[]; config: unknown[]; warnings: string[]; files: { path: string; size: number }[];
  safety: { verdict: "pass" | "warn" | "block"; findings: unknown[] } | null;
  events: { at: string; stage: string; message: string; detail?: string }[];
  queuePosition: number; finishedAt: string | null;
};

export async function svcHealth(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  try {
    const r = await call("/health", { timeoutMs: 4000 });
    return r.ok ? await r.json() : null;
  } catch { return null; }
}

export async function svcCreate(body: { id: string; prompt: string; mcVersion: string; pluginName?: string; baseBuildId?: string; changeRequest?: string }): Promise<ServiceBuild> {
  const r = await call("/builds", { method: "POST", body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}

