"use strict";
// Request routing for the Mod Builder: classify a request as simple / standard /
// complex and pick the generation and repair models for it.
//
// Two classifiers:
//   heuristic (default): deterministic feature count over the request text. Free,
//     instant, and reproducible (same prompt -> same route, which also makes
//     costs predictable).
//   haiku: one tiny Claude Haiku call that answers with a single word. Measured
//     against the heuristic on the fixed eval set (services/modbuilder/eval); see
//     docs "AI Mod Builder: tuning". Kept for comparison, not the default.
//
// Everything is configurable via env (read once at start):
//   MB_ROUTING            on (default) | off  (off = MB_MODEL for every call, the pre-tuning behaviour)
//   MB_CLASSIFIER         heuristic (default) | haiku
//   MB_MODEL_SIMPLE       default claude-haiku-4-5-20251001
//   MB_MODEL_STANDARD     default claude-sonnet-5
//   MB_MODEL_COMPLEX      default claude-sonnet-5-5
//   MB_REPAIR_CHEAP_MODEL default claude-haiku-4-5-20251001 (first repair of a small compile error)
//   MB_REPAIR_CHEAP_FIRST on (default) | off
//   MB_REPAIR_SMALL_MAX   default 3 (compile errors at or below this count are "small")
//   MB_ROUTE_SIMPLE_MAX   default 3   (score below this -> simple)
//   MB_ROUTE_COMPLEX_MIN  default 8   (score at or above this -> complex)

const HAIKU = "claude-haiku-4-5-20251001";
const env = (k, d) => (process.env[k] && process.env[k].trim()) || d;
const num = (k, d) => { const n = parseFloat(process.env[k] || ""); return Number.isFinite(n) ? n : d; };

const CFG = {
  routing: env("MB_ROUTING", "on") !== "off",
  classifier: env("MB_CLASSIFIER", "heuristic"),
  models: {
    simple: env("MB_MODEL_SIMPLE", HAIKU),
    standard: env("MB_MODEL_STANDARD", "claude-sonnet-5"),
    complex: env("MB_MODEL_COMPLEX", "claude-sonnet-5-5"),
  },
  repairCheapModel: env("MB_REPAIR_CHEAP_MODEL", HAIKU),
  repairCheapFirst: env("MB_REPAIR_CHEAP_FIRST", "on") !== "off",
  repairSmallMax: num("MB_REPAIR_SMALL_MAX", 3),
  simpleMax: num("MB_ROUTE_SIMPLE_MAX", 3),
  complexMin: num("MB_ROUTE_COMPLEX_MIN", 8),
};

// Each matching group adds its weight once. Weights reflect how much code and
// API surface a feature usually pulls in (and how often it broke in real builds).
const FEATURES = [
  ["gui", 2, /\b(gui|menus?|chest (menu|gui)|inventory (menu|gui)|clicking|click(s|ed)? (on )?(an?|the|one) )/],
  ["persist", 1, /\b(saved?|persist\w*|stored?|survive|between restarts|across restarts|to (a )?file|to disk|database)\b/],
  ["scoreboard", 2, /\b(scoreboard|sidebar|tab ?list|leaderboard|top \d+)\b/],
