// Runtime smoke bot for rtcheck.py: joins a throwaway offline-mode Paper server,
// gets op over RCON, runs every plugin command once with no arguments (usage /
// default paths), stays online long enough for minute timers to fire, then
// stops the server. Run with node_modules from mineflayer + rcon-client.
//   RT_PORT RT_RCON RT_VERSION RT_COMMANDS='["/heal","/fly"]' RT_STAY_MS
const mineflayer = require("mineflayer");
const { Rcon } = require("rcon-client");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const port = +process.env.RT_PORT, rport = +process.env.RT_RCON;
  const cmds = JSON.parse(process.env.RT_COMMANDS || "[]");
  const stay = +(process.env.RT_STAY_MS || 70000);
  const out = { joined: false, chat: [], kicked: null, error: null };
  let rcon;
  try {
    rcon = await Rcon.connect({ host: "127.0.0.1", port: rport, password: "rtcheck-local" });
    const bot = mineflayer.createBot({ host: "127.0.0.1", port, username: "RtBot", version: process.env.RT_VERSION, auth: "offline" });
    bot.on("messagestr", (m) => { if (out.chat.length < 200) out.chat.push(m.slice(0, 200)); });
    bot.on("kicked", (r) => { out.kicked = String(typeof r === "string" ? r : JSON.stringify(r)).slice(0, 300); });
    bot.on("error", (e) => { out.error = String(e.message).slice(0, 300); });
    await Promise.race([new Promise((r) => bot.once("spawn", r)), sleep(60000)]);
    out.joined = !!bot.entity;
    if (out.joined) {
      await sleep(2000);
      await rcon.send("op RtBot");
      await sleep(1000);
      for (const c of cmds) { bot.chat(c); await sleep(1500); }
      const t0 = Date.now();
      while (Date.now() - t0 < stay) { await sleep(5000); if (!bot.entity) break; bot.setControlState("forward", true); await sleep(400); bot.setControlState("forward", false); }
      bot.quit();
    }
  } catch (e) { out.error = String(e && e.message || e).slice(0, 300); }
  try { if (rcon) { await rcon.send("stop"); await rcon.end(); } } catch { /* server going down */ }
  console.log(JSON.stringify(out));
  process.exit(0);
})();

