#!/usr/bin/env python3
"""Mine Mod Builder build records for candidate failure rules. HUMAN REVIEW ONLY:
this never edits rules/failure-rules.json. Run on the build VM:

  python3 mine-rules.py [--builds /var/lib/modbuilder/data/builds] [--rules ../rules/failure-rules.json]
                        [--rt /root/mbeval/<tag>/rt.jsonl ...] [--since 2026-10-07] [--json]

Looks at: compiler errors that triggered repairs (events "Error details"),
the final error of failed builds, pre-check hits, safety-scan findings, and
runtime failures from rtcheck.py output. Groups recurring causes by a normalised
signature and version, says whether an existing rule already covers it, and
drafts a rule line for each uncovered signature. Copy the good ones into
failure-rules.json by hand (with a 'source' note), bump its "version", rebuild.
"""
import argparse, glob, json, os, re, sys
from collections import defaultdict

ap = argparse.ArgumentParser()
ap.add_argument("--builds", default="/var/lib/modbuilder/data/builds")
ap.add_argument("--rules", default=os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "rules", "failure-rules.json"))
ap.add_argument("--rt", nargs="*", default=[])
ap.add_argument("--since", default="")
ap.add_argument("--json", action="store_true")
a = ap.parse_args()

rules = json.load(open(a.rules))["rules"]


def covered(v, probe):
    for r in rules:
        if not r.get("pattern"):
            continue
        if not any(x in ("*", v) for x in r.get("versions", ["*"])):
            continue
        if re.search(r["pattern"], probe, re.M):
            return r["id"]
    return None


SYM = re.compile(r"error: cannot find symbol\n.*?\n\s+symbol:\s+(variable|method|class)\s+([\w$]+)(?:\(([^)]*)\))?\n\s+location:\s+(?:(?:class|interface|enum)\s+([\w.$<>]+)|variable\s+\w+\s+of\s+type\s+([\w.$<>]+)|package\s+([\w.]+))", re.S)
GENERIC = re.compile(r"^[^\s:]+\.java:\d+: error: (.+)$", re.M)


def signatures(text):
    out = []
    for m in SYM.finditer(text):
        kind, name, args, cls, vtype, pkg = m.groups()
        where = cls or vtype or pkg or "?"
        where = where.split("<")[0].split(".")[-1] if not pkg else pkg
        if kind == "class":
            out.append((f"missing class {name} (in {where})", f"import {where}.{name};" if pkg else name))
        elif kind == "method":
            out.append((f"missing method {where}.{name}()", f".{name}("))
        else:
            out.append((f"missing field {where}.{name}", f"{where}.{name}"))
    for m in GENERIC.finditer(text):
        msg = m.group(1)
        if msg.startswith("cannot find symbol"):
            continue
        msg = re.sub(r"\b[a-z][\w]*\b(?=\s*\()", "m", msg)  # method names vary
        out.append((f"javac: {msg[:140]}", msg))
    for l in text.splitlines():
        l = l.strip()
        if l.startswith("- ") and ".java" not in l[:80]:
            out.append((f"validation: {re.sub(r'[\"(].*', '', l[2:])[:120]}", l))
    return out


groups = defaultdict(lambda: {"count": 0, "builds": [], "versions": set(), "probe": "", "examples": []})


def add(sig, v, bid, probe, example, kind):
    g = groups[(kind, sig, v)]
    g["count"] += 1
    if bid not in g["builds"]:
        g["builds"].append(bid)
    g["versions"].add(v)
    g["probe"] = probe
    if len(g["examples"]) < 2:
        g["examples"].append(example[:300])


n = 0
for f in sorted(glob.glob(os.path.join(a.builds, "*", "build.json"))):
    try:
        rec = json.load(open(f))
    except Exception:
        continue
    if a.since and (rec.get("createdAt") or "") < a.since:
        continue
    n += 1
    v, bid = rec.get("mcVersion"), rec.get("id")
    texts = [e.get("detail", "") for e in rec.get("events", []) if e.get("message") == "Error details" and e.get("detail")]
    if rec.get("status") == "failed" and rec.get("errorCode") == "compile" and rec.get("errorDetail"):
        texts.append(rec["errorDetail"])
    for t in texts:
        for sig, probe in signatures(t):
            add(sig, v, bid, probe, t, "compile")
    for h in rec.get("precheck") or []:
        add(f"precheck hit {h['rule']}", v, bid, "", h.get("where", ""), "precheck")
    for x in (rec.get("safety") or {}).get("findings", []):
        add(f"safety {x['severity']} {x['rule']}: {x['message']}", v, bid, "", x.get("evidence", ""), "safety")
    if rec.get("errorCode") in ("safety", "budget", "timeout"):
        add(f"build failed: {rec['errorCode']}", v, bid, "", rec.get("error") or "", "outcome")

for p in a.rt:
    for l in open(p):
        r = json.loads(l)
        if r.get("ok"):
            continue
        for e in r.get("exceptions") or ["(no exception text)"]:
            head = re.sub(r"dev\.nxeon\.plugins\.\w+", "<pkg>", e.split(" | ")[0])[:160]
            add(f"runtime: {head}", r["v"], r["key"], e, e, "runtime")
        if r.get("enableError"):
            add("runtime: plugin failed to enable", r["v"], r["key"], "", "", "runtime")

items = []
for (kind, sig, v), g in groups.items():
    cov = covered(v, g["probe"]) if g["probe"] and kind == "compile" else None
    draft = None
    m = re.match(r"missing field (\w+)\.(\w+)", sig)
    if m and not cov:
        draft = f"On {v} {m.group(1)}.{m.group(2)} does not exist: use <the name the API LOOKUP suggested>."
    m = re.match(r"missing method (\w+)\.(\w+)\(\)", sig)
    if m and not cov:
        draft = f"{m.group(1)} has no {m.group(2)}() (checked on {v}): use <correct method>."
    m = re.match(r"missing class (\w+) \(in ([\w.]+)\)", sig)
    if m and not cov:
        draft = f"{m.group(1)} is not in {m.group(2)}: import it from <correct package>."
    items.append({"kind": kind, "signature": sig, "version": v, "count": g["count"], "builds": g["builds"][:8], "coveredBy": cov, "draft": draft, "example": g["examples"][0] if g["examples"] else ""})
items.sort(key=lambda x: (x["coveredBy"] is not None, -x["count"], x["kind"], x["signature"]))

if a.json:
    print(json.dumps({"buildsScanned": n, "candidates": items}, indent=2))
    sys.exit(0)
print(f"# Candidate failure rules ({n} build records scanned)\n")
print("Uncovered first. Nothing here is applied automatically: review, then edit rules/failure-rules.json by hand.\n")
for it in items:
    flag = f"covered by `{it['coveredBy']}`" if it["coveredBy"] else "**NOT COVERED**"
    print(f"- [{it['kind']}] {it['signature']} on {it['version']} x{it['count']} ({flag}) builds: {', '.join(it['builds'])}")
    if it["draft"]:
        print(f"  - draft rule: {it['draft']}")

